Lemma ov_read_bytes_unfold : forall m a n,
  ov_read_bytes segs m a (S n) =
  match ov_byte m a with
  | Some b => match ov_read_bytes segs m (a + 1) n with
              | Some rest => Some (b :: rest) | None => None end
  | None => None
  end.
