Lemma page_of_access_byte : forall (a : word) (k : nat),
  let x := bv_unsigned (a + Z_to_bv 64 (Z.of_nat k)) in
  let p := bv_unsigned (page_base_of (bv_unsigned a + Z.of_nat k)) in
  p = ((x / page_size) * page_size)%Z /\ (p <= x < p + page_size)%Z.
Proof.
