Section Windows.
Variable L : list (word * word).

Lemma lazy_inv_windows_mono : forall S S' m,
  lazy_inv L S m ->
  incl (all_pages S) (all_pages S') ->
  (eager_used m + pages_total S' * page_size <= vm_limit (m_vmmaps m))%Z ->
