Lemma iv_subtract_within : forall a sz lo hi b m,
  (bv_unsigned a + bv_unsigned sz <= 2 ^ 64)%Z ->
  (hi <= 2 ^ 64)%Z ->
  In (b, m) (iv_subtract a sz lo hi) ->
  (bv_unsigned a <= bv_unsigned b)%Z
