Lemma lazy_range_okb_within : forall segs a sz b m,
  lazy_range_okb segs (a, sz) = true ->
  (bv_unsigned a <= bv_unsigned b)%Z ->
  (bv_unsigned b + bv_unsigned m <= bv_unsigned a + bv_unsigned sz)%Z ->
  lazy_range_okb segs (b, m) = true.
